#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("pomiary.txt");
    int n;
    int mn, mx, mnPos, mxPos, pos = 0;
    while (plik >> n) {
        pos++;
        if (pos == 1 || n < mn) { mn = n; mnPos = pos; }
        if (pos == 1 || n > mx) { mx = n; mxPos = pos; }
    }
    cout << "Minimum: " << mn << " (pozycja " << mnPos << ")" << endl;
    cout << "Maksimum: " << mx << " (pozycja " << mxPos << ")" << endl;
    cout << "Rozstep: " << mx - mn << endl;
    return 0;
}
